def bar(angle, length=9):
    k = length; g = np.zeros((k, k)); c = (k - 1) / 2; t = np.deg2rad(angle)
    for s in np.linspace(-c, c, 4 * k):
        g[int(round(c - s * np.sin(t))), int(round(c + s * np.cos(t)))] = 1.0
    return g
def corr(img, K):
    kh = K.shape[0]; H = img.shape[0] - kh + 1
    return np.array([[np.sum(img[i:i+kh, j:j+kh] * K) for j in range(H)] for i in range(H)])
def make_k(pos_w1, neg_from):
    K = np.zeros((5, 5))
    for i in range(5):
        for j in range(5):
            d = abs(i + j - 4)
            K[i, j] = 1.0 if d == 0 else (pos_w1 if d == 1 else (-1.0 if d >= neg_from else 0.0))
    neg = K < 0
    K[neg] = -K[~neg].sum() / neg.sum()   # zero-sum: uniform regions give 0
    return K
